func (q *Queries) SaveQuery(ctx context.Context, arg SaveQueryParams) (SavedQuery, error) {
	row := q.queryRow(ctx, q.saveQueryStmt, saveQuery,
		arg.ServiceID,
		arg.UserID,
		arg.Name,
		arg.Sql,
		arg.Now,
	)
	var i SavedQuery
	err := row.Scan(
		&i.ID,
		&i.ServiceID,
		&i.UserID,
		&i.Name,
		&i.Sql,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

