const setServiceDatabaseSettings = `-- name: SetServiceDatabaseSettings :one

UPDATE services SET database = ?1, database_url_variable = ?2
WHERE id = ?3
RETURNING id, environment_id, name, image, port, health_check_path, health_check_timeout_seconds, start_command, dockerfile_path, build_command, memory_mb, cpus, pending_settings, created_at, archived_at, "database", database_url_variable, template
`

type SetServiceDatabaseSettingsParams struct {
	Database            string
	DatabaseUrlVariable string
	ID                  int64
}

// Database panel (ADR 0016). Parameters compared to indexed columns are
// written `= +?` and limits `LIMIT +?` (docs/performance.md, the re-prepare
// pitfall); scope IDs use 0 for "none".
// Sets a service's database and database_url_variable settings. They apply
// immediately: no release, nothing staged.
func (q *Queries) SetServiceDatabaseSettings(ctx context.Context, arg SetServiceDatabaseSettingsParams) (Service, error) {
	row := q.queryRow(ctx, q.setServiceDatabaseSettingsStmt, setServiceDatabaseSettings, arg.Database, arg.DatabaseUrlVariable, arg.ID)
	var i Service
	err := row.Scan(
		&i.ID,
		&i.EnvironmentID,
		&i.Name,
		&i.Image,
		&i.Port,
		&i.HealthCheckPath,
		&i.HealthCheckTimeoutSeconds,
		&i.StartCommand,
		&i.DockerfilePath,
		&i.BuildCommand,
		&i.MemoryMb,
		&i.Cpus,
		&i.PendingSettings,
		&i.CreatedAt,
		&i.ArchivedAt,
		&i.Database,
		&i.DatabaseUrlVariable,
		&i.Template,
	)
	return i, err
}

const setTokenDataAccess = `-- name: SetTokenDataAccess :execrows
UPDATE tokens SET
    data_production = ?1,
    data_non_production = ?2,
    data_sensitive = ?3
WHERE id = ?4
`

type SetTokenDataAccessParams struct {
	DataProduction    *string
	DataNonProduction *string
	DataSensitive     *string
	ID                int64
}

// Sets a token's own data access; NULLs for all three make it follow the
// policy's tokens rule again.
func (q *Queries) SetTokenDataAccess(ctx context.Context, arg SetTokenDataAccessParams) (int64, error) {
	result, err := q.exec(ctx, q.setTokenDataAccessStmt, setTokenDataAccess,
		arg.DataProduction,
		arg.DataNonProduction,
		arg.DataSensitive,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

const updateSavedQuery = `-- name: UpdateSavedQuery :one
UPDATE saved_queries SET name = ?1, sql = ?2, updated_at = ?3
WHERE id = ?4 AND service_id = +?5 AND user_id = +?6
RETURNING id, service_id, user_id, name, sql, created_at, updated_at
`

type UpdateSavedQueryParams struct {
	Name      string
	Sql       string
	Now       time.Time
	ID        int64
	ServiceID int64
	UserID    int64
}

// Renames or edits one of the user's saved queries; no row (IsNotFound) if
// it isn't theirs on this database. Taking another query's name is a unique
// violation.
func (q *Queries) UpdateSavedQuery(ctx context.Context, arg UpdateSavedQueryParams) (SavedQuery, error) {
	row := q.queryRow(ctx, q.updateSavedQueryStmt, updateSavedQuery,
		arg.Name,
		arg.Sql,
		arg.Now,
		arg.ID,
		arg.ServiceID,
		arg.UserID,
	)
	var i SavedQuery
	err := row.Scan(
		&i.ID,
		&i.ServiceID,
		&i.UserID,
		&i.Name,
		&i.Sql,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

const upsertDataAccess = `-- name: UpsertDataAccess :one
INSERT INTO data_access (service_id, engine, server_version, reader_secret, writer_secret, set_up_at, set_up_by)
VALUES (?, ?, ?, ?, ?, ?, ?)
ON CONFLICT (service_id) DO UPDATE SET
    engine = excluded.engine, server_version = excluded.server_version,
    reader_secret = excluded.reader_secret, writer_secret = excluded.writer_secret,
    grants_synced_hash = '', set_up_at = excluded.set_up_at, set_up_by = excluded.set_up_by
RETURNING service_id, engine, server_version, reader_secret, writer_secret, grants_synced_hash, set_up_at, set_up_by
`

type UpsertDataAccessParams struct {
	ServiceID     int64
	Engine        string
	ServerVersion string
	ReaderSecret  []byte
	WriterSecret  []byte
	SetUpAt       time.Time
	SetUpBy       string
}

// Records a setup or rotation: new sealed role passwords and who did it.
// The roles' grants are resynced afterwards, so the hash resets.
func (q *Queries) UpsertDataAccess(ctx context.Context, arg UpsertDataAccessParams) (DataAccess, error) {
	row := q.queryRow(ctx, q.upsertDataAccessStmt, upsertDataAccess,
		arg.ServiceID,
		arg.Engine,
		arg.ServerVersion,
		arg.ReaderSecret,
		arg.WriterSecret,
		arg.SetUpAt,
		arg.SetUpBy,
	)
	var i DataAccess
	err := row.Scan(
		&i.ServiceID,
		&i.Engine,
		&i.ServerVersion,
		&i.ReaderSecret,
		&i.WriterSecret,
		&i.GrantsSyncedHash,
		&i.SetUpAt,
		&i.SetUpBy,
	)
	return i, err
}
